const items = $input.all();
const videos = [];

for (const item of items) {
  const scraped = item.json?.data?.data || [];

  for (const video of scraped) {
    const title = video.title || '';
    const summary = video.news_summary || '';

    // Drop anything Firecrawl returned without usable content
    if (title !== '' && summary !== '') {
      videos.push({
        title: title.trim(),
        url: video.url || '',
        news_summary: summary.trim(),
      });
    }
  }
}

// Flatten every video into one plain-text block so the model gets a single prompt
// instead of one item per video.
let transcriptBlock = '';
for (let i = 0; i < videos.length; i++) {
  const v = videos[i];
  transcriptBlock += `VIDEO #${i + 1}\n`;
  transcriptBlock += `TITLE: ${v.title}\n`;
  transcriptBlock += `URL: ${v.url}\n`;
  transcriptBlock += `CONTENT / TRANSCRIPT:\n${v.news_summary}\n`;
  transcriptBlock += `=========================================\n\n`;
}

return [
  {
    json: {
      total_videos: videos.length,
      transcript_block: transcriptBlock,
    },
  },
];

